package com.mamtrex.hospital.appointment; import com.mamtrex.hospital.organization.Branch; import com.mamtrex.hospital.shared.BaseEntity; import jakarta.persistence.*;
@Entity @Table(name="appointments") public class Appointment extends BaseEntity { private String patientId; private String professionalId; private String scheduledAt; /* Task 9 (docs/plan3.md §4.6): the explicit bounded duration and the server-computed half-open window end (scheduledAt + durationMinutes). Both are stored in the same canonical LocalDateTime.toString() representation as scheduledAt so repository range comparisons stay order-safe. They are null only on legacy rows created before Task 9 through the original 6-arg constructor seam — those rows carry no computable window and are honestly excluded from conflict candidates instead of being compared with an invented duration. durationMinutes itself is a bounded engineering validation range (5-480) for the synthetic demo, never clinical policy. */ private Integer durationMinutes; private String endsAt; private String type; private String status; /* Branch ownership (docs/plan3.md Task 4): workflow creates derive it from the acting context, never client input; null is the deliberate legacy seam for pre-Task-4 rows, which stay invisible through branch-scoped endpoints. The String-typed reference columns stay the established legacy persistence representation. */ @ManyToOne @JoinColumn(name="branch_id") private Branch branch; protected Appointment(){} public Appointment(Branch branch, String patientId, String professionalId, String scheduledAt, String type, String status){this.branch=branch; this.patientId=patientId; this.professionalId=professionalId; this.scheduledAt=scheduledAt; this.type=type; this.status=status;} public Appointment(Branch branch, String patientId, String professionalId, String scheduledAt, Integer durationMinutes, String endsAt, String type, String status){this.branch=branch; this.patientId=patientId; this.professionalId=professionalId; this.scheduledAt=scheduledAt; this.durationMinutes=durationMinutes; this.endsAt=endsAt; this.type=type; this.status=status;} public String getPatientId(){return patientId;} public String getProfessionalId(){return professionalId;} public String getScheduledAt(){return scheduledAt;} public Integer getDurationMinutes(){return durationMinutes;} public String getEndsAt(){return endsAt;} public String getType(){return type;} public String getStatus(){return status;} public Branch getBranch(){return branch;} }
